    for (i = 0; i < GEN.length; i++) if (ENEMY[GEN[i]].first <= w) { av.push(GEN[i]); tot += ENEMY[GEN[i]].weight; }
    for (i = 0; i < n; i++) {
      var r = rng() % tot;
