      out.push(av[j]);
    }
    return out;
  }
  function armourOf(type, w) { return type === 'grunt' ? Math.floor(w / 4) : type === 'brute' ? 6 + w : 0; }
  function tierDmg(d, tier) { for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
  function view(e) {
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor,
