            log.push([tick, 'B', s, def.idx]);
            if (rec) rec.event('B', tick, s, def.idx);
          } else if (a.op === 'upgrade') {
            if (!T || T.tier >= 3) continue;
            var c = T.tier === 1 ? T.def.cost : 2 * T.def.cost;
            if (gold < c) continue;
            gold -= c; T.spent += c; T.tier++;
            T.dmg = tierDmg(T.def.dmg, T.tier); T.range = T.def.range + 30 * (T.tier - 1);
