      break;
    }
    enemies = keep;
    // 4. age & heal
    for (i = 0; i < enemies.length; i++) {
      var h = enemies[i];
      h.age++;
      if (h.type === 'mender' && h.age % 20 === 0) {
        for (var j = 0; j < enemies.length; j++) {
          var o = enemies[j], dx = o.x - h.x, dy = o.y - h.y;
          if (dx * dx + dy * dy <= 22500) { o.hp += Math.floor(o.maxHp * 8 / 100); if (o.hp > o.maxHp) o.hp = o.maxHp; }
