      if (t.cd > 0) { t.cd--; if (t.cd > 0) continue; }
      var d = t.def, r2 = t.range * t.range, cands = [];
      for (i = 0; i < enemies.length; i++) {
        var c5 = enemies[i];
        if (c5.air ? !d.air : !d.ground) continue;
        var ex = c5.x - t.x, ey = c5.y - t.y;
