        for (i = 0; i < cands.length; i++) if (cands[i].id === rid) { tgt = cands[i]; break; }
      }
      if (!tgt) {
        var bestRem = Infinity;
        for (i = 0; i < cands.length; i++) {
          var rem = (cands[i].air ? AIR.len : GROUND.len) - cands[i].progress;
          if (rem < bestRem) { bestRem = rem; tgt = cands[i]; }
        }
      }
      var hits;
      if (d.splash > 0) {
        hits = []; var sp2 = d.splash * d.splash;
        for (i = 0; i < enemies.length; i++) {
          var u = enemies[i];
          if (u.air ? !d.air : !d.ground) continue;
          var ux = u.x - tgt.x, uy = u.y - tgt.y;
          if (ux * ux + uy * uy <= sp2) hits.push(u);
        }
      } else hits = [tgt];
      var anyDead = false;
      for (i = 0; i < hits.length; i++) {
        var v = hits[i], dm = d.pierce ? t.dmg : Math.max(1, t.dmg - v.armor);
        v.hp -= dm;
        if (d.slow > 0) v.slow = d.slow;
        if (v.hp <= 0) anyDead = true;
      }
      t.cd = d.period;
      if (rec) rec.event('X', tick, t, tgt);
      if (anyDead) {
        var alive = [], dead = [];
        for (i = 0; i < enemies.length; i++) (enemies[i].hp <= 0 ? dead : alive).push(enemies[i]);
        enemies = alive;
        for (i = 0; i < dead.length; i++) {
          var k = dead[i];
          gold += k.bounty;
          log.push([tick, 'K', k.id, s5]);
          if (rec) rec.event('K', tick, k, s5);
