function createStrategy() {
  var P = (typeof STRAT_PARAMS !== 'undefined' && STRAT_PARAMS) ? STRAT_PARAMS : {
    types: ['bolt','bolt','cannon','cannon','lance','flak','lance','cannon','flak','lance','bolt','cannon','lance','flak','bolt','bolt'],
    order: [2,3,5,4,6,7,8,2,3,4,10,12,13,9,11,6,7,5,8,1,0,14,15,2,3,4,6,7,8,5,10,12,13,9,11,10,12,13,9,11,1,0,14,15,1,0,14,15],
    hoard: 0, safeRem: 2000, wM: 3, wB: 1, urg: 600, urgK: 4
  };
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DMG = { bolt: [26, 41, 65], cannon: [60, 96, 153], frost: [10, 16, 25], lance: [180, 288, 460], flak: [40, 64, 102] };
  var ptr = 0;
  function plan(s) {
    var acts = [], gold = s.gold, i;
    var tier = [], typ = [];
    for (i = 0; i < 16; i++) { var t = s.slots[i].turret; tier.push(t ? t.tier : 0); typ.push(t ? t.type : null); }
    // threat: deepest living enemy
    var minRem = 1e9;
    for (i = 0; i < s.enemies.length; i++) { var e = s.enemies[i]; if (e.remaining < minRem) minRem = e.remaining; }
    var reserve = (minRem > P.safeRem && s.baseHp >= 10) ? P.hoard : 0;
    while (ptr < P.order.length && acts.length < 32) {
      var sl = P.order[ptr], c;
      if (tier[sl] === 0) c = COST[P.types[sl]];
      else if (tier[sl] === 1) c = COST[typ[sl]];
      else if (tier[sl] === 2) c = 2 * COST[typ[sl]];
      else { ptr++; continue; }
      if (gold - c < reserve) break;
      if (tier[sl] === 0) { acts.push({ op: 'build', slot: sl, type: P.types[sl] }); typ[sl] = P.types[sl]; }
      else acts.push({ op: 'upgrade', slot: sl });
      tier[sl]++; gold -= c; ptr++;
    }
    return acts;
  }
  function target(tu, cs) {
    var n = cs.length;
    if (n === 1) return cs[0].id;
    var type = tu.type, d = DMG[type][tu.tier - 1], best = -1, bestS = -1e18, i, j, c, sc;
    var splash = type === 'cannon' ? 8100 : type === 'flak' ? 4900 : 0;
    for (i = 0; i < n; i++) {
      c = cs[i];
      if (splash) {
        sc = 0;
        for (j = 0; j < n; j++) {
          var o = cs[j], dx = o.x - c.x, dy = o.y - c.y;
          if (dx * dx + dy * dy <= splash) {
            var dm = d - o.armor; if (dm < 1) dm = 1; if (dm > o.hp) dm = o.hp;
            sc += dm * (o.type === 'mender' ? P.wM : 1) * (o.remaining < P.urg ? P.urgK : 1);
          }
        }
      } else if (type === 'frost') {
        sc = (c.slowed ? 0 : 1000000) + c.hp / (c.remaining + 200);
      } else {
        var dm2 = type === 'lance' ? d : d - c.armor; if (dm2 < 1) dm2 = 1; if (dm2 > c.hp) dm2 = c.hp;
        sc = dm2 * (c.type === 'mender' ? P.wM : 1) * (c.remaining < P.urg ? P.urgK : 1);
        if (type === 'bolt' && c.air) sc *= P.wB;
      }
      sc = sc * 10000 - c.remaining;
      if (sc > bestS) { bestS = sc; best = c.id; }
    }
    return best;
  }
  return { plan: plan, target: target };
}

