function ri(n) { return Math.floor(rnd() * n); }
var seeds = []; for (var i = 0; i < NSEEDS; i++) seeds.push(5000 + i * 7919);
function evalP(p) {
  STRAT_PARAMS = p; var tot = 0;
  for (var i = 0; i < seeds.length; i++) tot += rampartSimulate(createStrategy, seeds[i], 12020).score;
  return tot / seeds.length;
}
var TYPES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
var cur = JSON.parse(INIT);
var NUM = NUMSPEC; // {name:[min,max,step]}
function mutate(p) {
  var q = JSON.parse(JSON.stringify(p)), r = rnd();
  if (r < 0.4) { var i = ri(q.order.length), j = rnd() < 0.6 ? Math.max(0, Math.min(q.order.length - 1, i + ri(9) - 4)) : ri(q.order.length); var v = q.order.splice(i, 1)[0]; q.order.splice(j, 0, v); }
  else if (r < 0.55) { q.types[ri(16)] = TYPES[ri(5)]; }
  else if (r < 0.65) { var a = ri(16), b = ri(16), t = q.types[a]; q.types[a] = q.types[b]; q.types[b] = t; }
  else if (r < 0.72) { var a2 = ri(q.order.length), b2 = ri(q.order.length), t2 = q.order[a2]; q.order[a2] = q.order[b2]; q.order[b2] = t2; }
  else { var ks = Object.keys(NUM); if (!ks.length) return mutate(p); var k = ks[ri(ks.length)], sp = NUM[k]; var nv = q[k] + (ri(2) ? 1 : -1) * sp[2] * (1 + ri(3)); q[k] = Math.max(sp[0], Math.min(sp[1], nv)); }
  if (rnd() < 0.25) return mutate(q);
  return q;
}
var curS = evalP(cur), best = cur, bestS = curS;
print('init', curS);
var T0 = 0.15;
for (var it = 0; it < ITERS; it++) {
  var T = T0 * (1 - it / ITERS);
  var c = mutate(cur), s = evalP(c);
  if (s >= curS || rnd() < Math.exp((s - curS) / Math.max(T, 1e-6))) { cur = c; curS = s; if (s > bestS) { best = c; bestS = s; } }
  if (it % 200 === 199) print('it', it, curS, bestS);
}
print('BEST', bestS, JSON.stringify(best));

