  // per turret type: weight of each enemy type
  var W = {
    bolt: { grunt: 1, runner: P.wRuB, wisp: P.wWiB, brute: P.wBr, splitter: P.wSp, mender: P.wM, splitling: P.wSl },
    cannon: { grunt: 1, runner: P.wRuC, wisp: 1, brute: P.wBr, splitter: P.wSp, mender: P.wM, splitling: P.wSl },
    lance: { grunt: 1, runner: P.wRuL, wisp: 1, brute: P.wBrL, splitter: P.wSp, mender: P.wM, splitling: P.wSl },
    flak: { grunt: 1, runner: 1, wisp: 1, brute: 1, splitter: 1, mender: 1, splitling: 1 }
  };
  var ptr = 0;
  function plan(s) {
    var acts = [], gold = s.gold, i;
    var tier = [], typ = [];
    for (i = 0; i < 16; i++) { var t = s.slots[i].turret; tier.push(t ? t.tier : 0); typ.push(t ? t.type : null); }
    var minT = 1e9;
    for (i = 0; i < s.enemies.length; i++) { var e = s.enemies[i], tl = e.remaining / (SPD[e.type] || 10); if (tl < minT) minT = tl; }
