      for (i = 0; i < n; i++) {
        c = cs[i];
        sc = (c.slowed ? 0 : 1000) * (c.type === 'runner' ? P.fwRu : c.type === 'wisp' ? P.fwWi : 1) + 100 / (1 + c.remaining / (SPD[c.type] || 10));
