      }
      return best;
    }
    var w = W[type], splash = type === 'cannon' ? 8100 : type === 'flak' ? 4900 : 0, pierce = type === 'lance';
    var val = new Array(n);
    for (i = 0; i < n; i++) {
      o = cs[i];
      dm = pierce ? d : d - o.armor; if (dm < 1) dm = 1;
      v = dm >= o.hp ? o.hp * (1 + P.kB) : dm;
      v *= w[o.type] || 1;
      if (o.remaining < P.urgT * (SPD[o.type] || 10)) v *= P.urgK;
      val[i] = v;
    }
    for (i = 0; i < n; i++) {
      c = cs[i];
      if (splash) {
        sc = 0;
        for (j = 0; j < n; j++) { o = cs[j]; var dx = o.x - c.x, dy = o.y - c.y; if (dx * dx + dy * dy <= splash) sc += val[j]; }
      } else sc = val[i];
      sc = sc * 10000 - c.remaining;
      if (sc > bestS) { bestS = sc; best = c.id; }
    }
    return best;
  }
  return { plan: plan, target: target };
}

