 [200,function(){snap('t0.2 countdown3')}],
 [1400,function(){snap('t1.4 countdown2')}],
 [2500,function(){snap('t2.5 countdown1')}],
 [3400,function(){snap('t3.4 playing')}],
 [4400,function(){snap('t4.4 playing'); $('btn-toggle').click(); snap('paused')}],
 [5000,function(){snap('still paused'); $('btn-toggle').click(); snap('resumed')}],
 [5600,function(){snap('playing again'); document.querySelector('[data-speed="2.0"]').click(); snap('speed2 '+document.querySelector('.is-active').textContent+' checked='+[].map.call(document.querySelectorAll('.speed-pill'),function(p){return p.getAttribute('aria-checked')}).join(','))}],
 [6600,function(){snap('after 1s at 2x'); $('btn-refire').click(); snap('refire')}],
 [7200,function(){snap('refire hold 0.6s')}],
 [7900,function(){snap('after hold (playing 2x)')}],
 [8500,function(){var s=$('scrubber'); s.value='99.5'; s.dispatchEvent(new Event('input')); snap('scrubbed 99.5 paused'); $('btn-toggle').click();}],
 [9500,function(){snap('ended?'); $('btn-toggle').click(); snap('restart from ended')}],
 [10000,function(){snap('playing after ended'); $('btn-refire').click(); $('btn-toggle').click(); snap('toggle during hold -> paused at 0'); document.title='DONE '+JSON.stringify(out)+' REPORT '+JSON.stringify(window.BENCH_REPORT);}]
];
steps.forEach(function(s){setTimeout(s[1],s[0])});
window.addEventListener('error',function(e){document.title='ERR '+e.message});
})();</script></body>'''
open(d+'/fsm.html','w').write(h.replace('</body>',inj))

