import sys, json, socket, os, base64, struct, time, subprocess, urllib.request

class WS:
    def __init__(self, url):
        assert url.startswith('ws://')
        hostport, path = url[5:].split('/', 1)
        host, port = hostport.split(':')
        self.s = socket.create_connection((host, int(port)))
        key = base64.b64encode(os.urandom(16)).decode()
        self.s.sendall(('GET /%s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n\r\n' % (path, hostport, key)).encode())
        buf = b''
        while b'\r\n\r\n' not in buf: buf += self.s.recv(4096)
        self.buf = buf.split(b'\r\n\r\n', 1)[1]
    def send(self, text):
        data = text.encode(); n = len(data); mask = os.urandom(4)
        hdr = b'\x81'
        if n < 126: hdr += bytes([0x80 | n])
        elif n < 65536: hdr += bytes([0x80 | 126]) + struct.pack('>H', n)
        else: hdr += bytes([0x80 | 127]) + struct.pack('>Q', n)
        self.s.sendall(hdr + mask + bytes(b ^ mask[i % 4] for i, b in enumerate(data)))
    def _read(self, n):
        while len(self.buf) < n:
            c = self.s.recv(65536)
            if not c: raise EOFError
            self.buf += c
        r, self.buf = self.buf[:n], self.buf[n:]
        return r
    def recv(self):
        out = b''
        while True:
            h = self._read(2); fin = h[0] & 0x80; n = h[1] & 0x7f
            if n == 126: n = struct.unpack('>H', self._read(2))[0]
            elif n == 127: n = struct.unpack('>Q', self._read(8))[0]
            out += self._read(n)
            if fin: return out.decode('utf8', 'replace')

def main():
    chrome, url, w, h, tmp = sys.argv[1:6]
    script = open(sys.argv[6]).read()
    shot = sys.argv[7] if len(sys.argv) > 7 else None
    port = 9333
    p = subprocess.Popen([chrome, '--headless', '--no-sandbox', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--autoplay-policy=no-user-gesture-required',
                          '--remote-debugging-port=%d' % port, '--window-size=%s,%s' % (w, h), '--user-data-dir=' + tmp, 'about:blank'], stderr=subprocess.DEVNULL, stdout=subprocess.DEVNULL)
    try:
        for _ in range(50):
            try:
                tabs = json.load(urllib.request.urlopen('http://127.0.0.1:%d/json' % port)); break
            except Exception: time.sleep(0.2)
        ws = WS([t for t in tabs if t['type'] == 'page'][0]['webSocketDebuggerUrl'])
        mid = [0]
        def call(method, params=None):
            mid[0] += 1; ws.send(json.dumps({'id': mid[0], 'method': method, 'params': params or {}}))
            while True:
                m = json.loads(ws.recv())
                if m.get('id') == mid[0]: return m
                if m.get('method') in ('Runtime.exceptionThrown',): print('EXC', json.dumps(m)[:600])
                if m.get('method') == 'Runtime.consoleAPICalled' and m['params']['type'] in ('error', 'warning'): print('CONSOLE', json.dumps(m['params']['args'])[:400])
        call('Runtime.enable'); call('Page.enable')
        call('Page.navigate', {'url': url})
        time.sleep(1.5)
        r = call('Runtime.evaluate', {'expression': script, 'awaitPromise': True, 'returnByValue': True})
        print(r.get('result', {}).get('result', {}).get('value', r))
        if shot:
            r = call('Page.captureScreenshot', {'format': 'png'})
            open(shot, 'wb').write(base64.b64decode(r['result']['data']))
    finally:
        p.terminate()
main()

